// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListCommits Default-branch commits merged across repositories, newest first, one page at a time
	// (GET /commits)
	ListCommits(ctx context.Context, request ListCommitsRequestObject) (ListCommitsResponseObject, error)
	// GetDashboard Groups with counts and latest activity, the latest commits and data health
	// (GET /dashboard)
	GetDashboard(ctx context.Context, request GetDashboardRequestObject) (GetDashboardResponseObject, error)
	// ListGroups All groups in configuration order, with member counts
	// (GET /groups)
	ListGroups(ctx context.Context, request ListGroupsRequestObject) (ListGroupsResponseObject, error)
	// GetGroup One group with its repositories
	// (GET /groups/{group})
	GetGroup(ctx context.Context, request GetGroupRequestObject) (GetGroupResponseObject, error)
	// ListRepos All repositories sorted by address, optionally of one group
	// (GET /repos)
	ListRepos(ctx context.Context, request ListReposRequestObject) (ListReposResponseObject, error)
	// GetRepo One repository; an old address redirects to the current one
	// (GET /repos/{owner}/{name})
	GetRepo(ctx context.Context, request GetRepoRequestObject) (GetRepoResponseObject, error)
	// ListDocs The repository's documents, README first, then docs/ in navigation order
	// (GET /repos/{owner}/{name}/docs)
	ListDocs(ctx context.Context, request ListDocsRequestObject) (ListDocsResponseObject, error)
	// GetDoc One rendered document
	// (GET /repos/{owner}/{name}/docs/{docId})
	GetDoc(ctx context.Context, request GetDocRequestObject) (GetDocResponseObject, error)
	// GetManifests The repository's package manifests, the technology they state and its internal dependencies
	// (GET /repos/{owner}/{name}/manifests)
	GetManifests(ctx context.Context, request GetManifestsRequestObject) (GetManifestsResponseObject, error)
	// GetSnapshot Data health; the web UI reads it to learn about new data
	// (GET /snapshot)
	GetSnapshot(ctx context.Context, request GetSnapshotRequestObject) (GetSnapshotResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// ListCommits operation middleware
func (sh *strictHandler) ListCommits(w http.ResponseWriter, r *http.Request, params ListCommitsParams) {
	var request ListCommitsRequestObject

	request.Params = params

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.ListCommits(ctx, request.(ListCommitsRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "ListCommits")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(ListCommitsResponseObject); ok {
		if err := validResponse.VisitListCommitsResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

